def img(src,alt='',cls='',prefix='',eager=False):return f'<img src="{prefix}{src}" alt="{e(alt)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">' if src else ''
def sectionhead(k,title,link='',label=''):
 return f'<div class="section-heading"><div><p class="eyebrow">{k}</p><h2>{title}</h2></div>'+ (f'<a class="text-link" href="{link}">{label} ↗</a>' if link else '')+'</div>'
