 return f'''<a class="article-card" href="articles/{a['id']}.html" data-search="{e(a['name'].lower())}"><div class="article-image">{img(a.get('image',''),a['name'])}<span class="round-button">↗</span></div><p class="eyebrow">ЗНАНИЯ / {max(1, round(sum(len(b['text'].split()) for b in a['blocks'])/180))} МИН ЧТЕНИЯ</p><h3>{e(a['name'])}</h3></a>'''
